import { getItemById, getUserById } from "@/lib/mock-data";
import { notFound } from "next/navigation";
import Image from "next/image";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Calendar, MapPin, User } from "lucide-react";
import { format } from "date-fns";
import { ClaimItemDialog } from "@/components/claim-item-dialog";

const getBadgeVariant = (status: 'lost' | 'found' | 'claimed') => {
  switch (status) {
    case 'lost':
      return 'destructive';
    case 'found':
      return 'default';
    case 'claimed':
      return 'secondary';
    default:
      return 'outline';
  }
};

const getItemHint = (category: string) => {
    switch (category.toLowerCase()) {
        case 'electronics': return 'gadget tech';
        case 'bottles': return 'water bottle';
        case 'books': return 'book study';
        case 'bags': return 'backpack travel';
        case 'keys': return 'keys lock';
        default: return 'object item';
    }
}

export default async function ItemDetailsPage({ params }: { params: { id: string } }) {
  const item = await getItemById(params.id);

  if (!item) {
    notFound();
  }

  const reporter = await getUserById(item.reportedBy);

  return (
    <div className="container mx-auto max-w-5xl px-4 py-8">
      <div className="grid grid-cols-1 gap-8 md:grid-cols-2">
        <div className="relative aspect-video w-full overflow-hidden rounded-lg">
          <Image
            src={item.imageUrl || "https://picsum.photos/1200/800"}
            alt={item.name}
            fill
            className="object-cover"
            data-ai-hint={getItemHint(item.category)}
          />
        </div>
        <div className="flex flex-col space-y-6">
          <div>
            <Badge variant={getBadgeVariant(item.status)} className="capitalize mb-2 text-sm">{item.status}</Badge>
            <h1 className="text-4xl font-bold tracking-tight">{item.name}</h1>
          </div>

          <p className="text-lg text-muted-foreground">{item.description}</p>

          <Card>
            <CardHeader>
              <CardTitle>Item Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4 text-sm">
              <div className="flex items-center">
                <MapPin className="mr-3 h-5 w-5 text-muted-foreground" />
                <span><strong className="font-medium">Location:</strong> {item.location}</span>
              </div>
              <div className="flex items-center">
                <Calendar className="mr-3 h-5 w-5 text-muted-foreground" />
                <span><strong className="font-medium">Date:</strong> {format(new Date(item.date), "PPP")}</span>
              </div>
              <div className="flex items-center">
                <User className="mr-3 h-5 w-5 text-muted-foreground" />
                <span><strong className="font-medium">Reported by:</strong> {reporter?.name || 'Anonymous'}</span>
              </div>
            </CardContent>
          </Card>
          
          {item.status === 'found' && (
            <ClaimItemDialog itemId={item.id} />
          )}
          {item.status === 'claimed' && (
            <div className="rounded-md bg-green-100 p-4 text-green-800">
                This item has been successfully claimed and returned to its owner.
            </div>
          )}

        </div>
      </div>
    </div>
  );
}
